WITH valid_web_events AS (SELECT *, DAY(event_time) AS event_time_day FROM web_events WHERE event_time < '2025-10-01' AND duration_sec = 138), web_events_stats AS (SELECT page, HOUR(event_time) AS event_hour, ROUND(AVG(event_time_day), 2) AS avg_event_time_day, SUM(event_time_day) AS total_event_time_day FROM valid_web_events GROUP BY page, HOUR(event_time)) SELECT * FROM web_events_stats WHERE avg_event_time_day < 33
